import{_ as a,o as e,c as d,a2 as s}from"./chunks/framework.Cd7uensT.js";const b=JSON.parse('{"title":"设备二维码信息牌","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features/device-qrcode.md","filePath":"guide/features/device-qrcode.md","lastUpdated":1794561975000}'),r={name:"guide/features/device-qrcode.md"};function o(i,t,n,l,h,p){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="设备二维码信息牌" tabindex="-1">设备二维码信息牌 <a class="header-anchor" href="#设备二维码信息牌" aria-label="Permalink to &quot;设备二维码信息牌&quot;">​</a></h1><p>设备二维码信息牌用于将设备基础信息打印后贴附在机柜设备上，现场人员扫码即可查看设备身份，无需登录系统，也无需翻阅台账。</p><blockquote><p><strong>版本要求</strong>：需 <strong>v2.6.0 及以上</strong>。</p></blockquote><h2 id="功能定位" tabindex="-1">功能定位 <a class="header-anchor" href="#功能定位" aria-label="Permalink to &quot;功能定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统方式</th><th>二维码信息牌</th></tr></thead><tbody><tr><td>手写标签，易脱落、字迹模糊</td><td>打印即贴，信息可随时重新生成</td></tr><tr><td>查设备信息需登录系统</td><td>扫码直接查看，无需账号</td></tr><tr><td>多台设备逐一核对效率低</td><td>支持批量生成与整页打印</td></tr></tbody></table><h2 id="单设备二维码" tabindex="-1">单设备二维码 <a class="header-anchor" href="#单设备二维码" aria-label="Permalink to &quot;单设备二维码&quot;">​</a></h2><h3 id="操作路径" tabindex="-1">操作路径 <a class="header-anchor" href="#操作路径" aria-label="Permalink to &quot;操作路径&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备管理 → 找到目标设备 → 操作列「二维码」</span></span></code></pre></div><h3 id="弹窗功能" tabindex="-1">弹窗功能 <a class="header-anchor" href="#弹窗功能" aria-label="Permalink to &quot;弹窗功能&quot;">​</a></h3><p>弹窗采用左右布局：</p><table tabindex="0"><thead><tr><th>区域</th><th>内容</th></tr></thead><tbody><tr><td>左侧</td><td>信息牌实时预览（字段勾选变化即时反映）</td></tr><tr><td>右侧</td><td>对外展示字段勾选列表</td></tr><tr><td>底部</td><td>下载 PNG / 打印 A4 / 复制二维码链接</td></tr></tbody></table><h3 id="可选字段" tabindex="-1">可选字段 <a class="header-anchor" href="#可选字段" aria-label="Permalink to &quot;可选字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>默认勾选</th><th>是否可取消</th><th>说明</th></tr></thead><tbody><tr><td>设备编号</td><td>是</td><td><strong>否</strong></td><td>核心标识，强制包含，保证扫码唯一绑定设备</td></tr><tr><td>名称</td><td>是</td><td>是</td><td>设备名称</td></tr><tr><td>类型</td><td>是</td><td>是</td><td>服务器 / 交换机 / 路由器 / 存储设备</td></tr><tr><td>型号</td><td>是</td><td>是</td><td>-</td></tr><tr><td>序列号</td><td>是</td><td>是</td><td>资产标识</td></tr><tr><td>所在位置</td><td>是</td><td>是</td><td>机房 / 机柜 / U 位</td></tr><tr><td>状态</td><td>是</td><td>是</td><td>运行中 / 维护中 / 离线 / 故障 / 空闲</td></tr><tr><td>IP 地址</td><td><strong>否</strong></td><td>是</td><td>见下方安全说明</td></tr><tr><td>描述/备注</td><td><strong>否</strong></td><td>是</td><td>见下方安全说明</td></tr></tbody></table><h3 id="输出方式" tabindex="-1">输出方式 <a class="header-anchor" href="#输出方式" aria-label="Permalink to &quot;输出方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td>下载 PNG</td><td>导出信息牌图片</td><td>发送给打印店批量制作、贴入文档</td></tr><tr><td>打印 A4</td><td>浏览器打印，自动适配 A4 版式</td><td>现场直接打印</td></tr><tr><td>复制链接</td><td>复制二维码内的 URL</td><td>发送给同事，或粘贴到其他系统</td></tr></tbody></table><h2 id="批量二维码与打印" tabindex="-1">批量二维码与打印 <a class="header-anchor" href="#批量二维码与打印" aria-label="Permalink to &quot;批量二维码与打印&quot;">​</a></h2><h3 id="操作路径-1" tabindex="-1">操作路径 <a class="header-anchor" href="#操作路径-1" aria-label="Permalink to &quot;操作路径&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备管理 → 勾选多台设备 → 批量操作「二维码」</span></span></code></pre></div><h3 id="与单设备模式的差异" tabindex="-1">与单设备模式的差异 <a class="header-anchor" href="#与单设备模式的差异" aria-label="Permalink to &quot;与单设备模式的差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>单设备</th><th>批量</th></tr></thead><tbody><tr><td>字段配置</td><td>可自定义</td><td>顶部统一勾选，应用到全部卡片</td></tr><tr><td>预览</td><td>单个大图</td><td>卡片区横向换行排列，可滚动</td></tr><tr><td>打印</td><td>单张 A4</td><td>一页多张，专用打印样式</td></tr></tbody></table><h3 id="打印样式隔离" tabindex="-1">打印样式隔离 <a class="header-anchor" href="#打印样式隔离" aria-label="Permalink to &quot;打印样式隔离&quot;">​</a></h3><p>同一页面可能同时存在多个二维码预览区域。批量打印期间，组件会给 <code>body</code> 添加 <code>qr-batch-printing</code> 标记类，打印样式据此<strong>只输出批量打印区域</strong>，隐藏其他预览区域，避免打印出意外的内容。</p><h2 id="二维码内容与部署要求" tabindex="-1">二维码内容与部署要求 <a class="header-anchor" href="#二维码内容与部署要求" aria-label="Permalink to &quot;二维码内容与部署要求&quot;">​</a></h2><h3 id="url-结构" tabindex="-1">URL 结构 <a class="header-anchor" href="#url-结构" aria-label="Permalink to &quot;URL 结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{当前站点 origin}/p/devices/{deviceId}?fields={勾选字段，逗号分隔}</span></span></code></pre></div><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://idc.example.com/p/devices/SRV-0001?fields=deviceId,name,type,model,serialNumber,position,status</span></span></code></pre></div><h3 id="关键部署要求" tabindex="-1">关键部署要求 <a class="header-anchor" href="#关键部署要求" aria-label="Permalink to &quot;关键部署要求&quot;">​</a></h3><blockquote><p><strong>二维码内嵌的是绝对地址，由生成时的浏览器 <code>window.location.origin</code> 决定。</strong></p></blockquote><p>这意味着：</p><table tabindex="0"><thead><tr><th>情况</th><th>后果</th></tr></thead><tbody><tr><td>生成时使用 <code>localhost</code> 访问</td><td>打印出的二维码指向 <code>http://localhost:8000/...</code>，其他设备扫码无法访问</td></tr><tr><td>生成时使用内网 IP，扫码人在同一内网</td><td>正常</td></tr><tr><td>生成时使用正式域名</td><td>正常，推荐</td></tr></tbody></table><p><strong>正确做法</strong>：在正式域名可访问后（或至少使用将被长期使用的内网域名 / IP）再生成并打印二维码。</p><h3 id="服务端对应端点" tabindex="-1">服务端对应端点 <a class="header-anchor" href="#服务端对应端点" aria-label="Permalink to &quot;服务端对应端点&quot;">​</a></h3><p>二维码指向的 <code>/p/devices/{deviceId}</code> 是<strong>完全免鉴权</strong>的公开页面，详见 <a href="/idc_assest-docs/api/system-observability.html#公开设备信息牌">公开设备信息牌</a>。</p><h2 id="安全说明" tabindex="-1">安全说明 <a class="header-anchor" href="#安全说明" aria-label="Permalink to &quot;安全说明&quot;">​</a></h2><h3 id="字段白名单机制" tabindex="-1">字段白名单机制 <a class="header-anchor" href="#字段白名单机制" aria-label="Permalink to &quot;字段白名单机制&quot;">​</a></h3><p>公开页面<strong>不接受任意字段</strong>，仅渲染白名单内的固定字段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deviceId, name, type, model, serialNumber, position, status</span></span></code></pre></div><p>即使 URL 中显式指定 <code>?fields=ipAddress,description</code>，服务端也会忽略这些字段。</p><h3 id="为什么默认不含-ip-地址与备注" tabindex="-1">为什么默认不含 IP 地址与备注 <a class="header-anchor" href="#为什么默认不含-ip-地址与备注" aria-label="Permalink to &quot;为什么默认不含 IP 地址与备注&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险</th><th>说明</th></tr></thead><tbody><tr><td>IP 地址泄露网络位置</td><td>内网 IP 段本身即暴露网络架构信息</td></tr><tr><td>备注可能含敏感内容</td><td>运维备注常含「待报废」「涉密项目」「临时借用」等内部信息</td></tr><tr><td>扫码人不可控</td><td>信息牌贴在现场，任何经过的人都能扫</td></tr></tbody></table><p>若确有在信息牌上展示 IP 的需求，请在勾选时确认该机房的人员进出管控足够严格。</p><h3 id="输出转义" tabindex="-1">输出转义 <a class="header-anchor" href="#输出转义" aria-label="Permalink to &quot;输出转义&quot;">​</a></h3><p>服务端渲染 HTML 前对所有字段执行 HTML 转义，防止设备名称或备注中的特殊字符造成 XSS。</p><h2 id="典型使用流程" tabindex="-1">典型使用流程 <a class="header-anchor" href="#典型使用流程" aria-label="Permalink to &quot;典型使用流程&quot;">​</a></h2><h3 id="新机房设备上架后批量贴牌" tabindex="-1">新机房设备上架后批量贴牌 <a class="header-anchor" href="#新机房设备上架后批量贴牌" aria-label="Permalink to &quot;新机房设备上架后批量贴牌&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 确认系统部署在长期使用的域名 / IP 上</span></span>
<span class="line"><span>2. 设备管理 → 筛选本批新设备 → 批量选中</span></span>
<span class="line"><span>3. 批量二维码 → 勾选展示字段（默认即可）</span></span>
<span class="line"><span>4. 预览确认无误 → 打印</span></span>
<span class="line"><span>5. 现场贴附到设备前面板或机柜侧方</span></span></code></pre></div><h3 id="已有标签的替换" tabindex="-1">已有标签的替换 <a class="header-anchor" href="#已有标签的替换" aria-label="Permalink to &quot;已有标签的替换&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 逐个生成，或按机柜批量生成</span></span>
<span class="line"><span>2. 下载 PNG 后统一排版印刷</span></span>
<span class="line"><span>3. 保留原标签至新标签验证无误</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：扫码后显示「设备不存在」？</strong></p><p>可能原因：</p><ol><li>二维码生成时设备尚未保存到数据库</li><li>设备已被删除</li><li>设备编号包含特殊字符导致 URL 编码异常</li></ol><p>处理：重新生成二维码。</p><p><strong>Q：扫码后页面样式错乱？</strong></p><p>公开页面为独立 HTML，不使用前端框架资源。若显示异常，通常为浏览器缓存了旧版本页面，强制刷新即可。</p><p><strong>Q：能否在信息牌上加公司 Logo？</strong></p><p>当前信息牌由服务端 HTML 模板渲染，不含 Logo。如需定制，可修改 <code>backend/routes/public.js</code> 中的 <code>renderCardHtml</code> 模板。</p><p><strong>Q：批量打印时只打出了第一页？</strong></p><p>在浏览器打印对话框中确认「缩放」设置为「适应页面大小」，并检查纸张是否为 A4。批量区采用横向换行布局，每页容纳数量取决于浏览器缩放比例。</p><p><strong>Q：二维码能否打印在金属设备表面？</strong></p><p>普通纸张贴附在金属表面易脱落。建议使用工业级标签纸 + 覆膜，或打印在 PET 材质标签上。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/idc_assest-docs/api/system-observability.html#公开设备信息牌">公开设备信息牌接口</a></li><li><a href="./device-management.html">设备管理</a></li><li><a href="./room-management.html">机房管理</a></li></ul>`,64)])])}const u=a(r,[["render",o]]);export{b as __pageData,u as default};
